// One-bit capture register, in a separate register for each bit of the input
// signal. The outputs are ORed together to produce the final capture signal.
module capture_register (
    input clk,
    input reset,
    input in,
    output reg out
);
    reg next;
    always @(posedge clk) begin
        if (reset) next <= 1'b0;
        else next <= in;
    end
    always @(posedge clk) begin
        if (reset) out <= 1'b0;
        else if (in == 1'b0 && next == 1'b1) out <= 1'b1;
        else out <= 1'b0;
    end
endmodule

