module CaptureOneShot (
    input  clk,
    input  reset,
    input  in,
    output reg out
);
    reg [1:0] state;
    reg next;
    always @(*) begin
        next = in & ~state[0];
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            out <= 1'b0;
        end else begin
            case (state)
                2'b00: begin
                    if (next) state <= 2'b01;
                end
                2'b01: begin
                    state <= 2'b10;
                end
                2'b10: begin
                    if (!next) state <= 2'b00;
                end
            endcase
            out <= (state == 2'b10);
        end
    end
endmodule

